function buildDeviceBlock(device_id) {
    return {
        manufacturer: "PA1DVB",
        model: "Node-Red",
        name: "BatteryControl",
        ids: [device_id]
    };
}

function createBinaryObject(root, name, varname, unique_id, payload_on = "ON", payload_off = "OFF")
{
    let device_id = extractDeviceId(unique_id);
    let vjson = {
        "stat_t": "~/" + varname + "/state",
        "dev": buildDeviceBlock(device_id),
        // Fix 12: Add origin block
        "origin": {
            "name": "Victron Node-RED",
            "sw_version": "1.0"
        }
    };
    vjson["~"] = root;
    vjson["name"] = name;
    vjson["payload_on"] = payload_on;
    vjson["payload_off"] = payload_off;
    vjson["uniq_id"] = unique_id;
    //vjson["val_tpl"] = "{{ value_json." + varname + " }}";
    return vjson;
}

